ep_flow_start.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "system").trim();
if (actor == "") {
  actor = "system";
}
let dryRun = body.dryRun == true || req.dryRun == true;
let workflowId = str(body.workflowId ?? req.workflowId ?? "").trim();

let workflows = vdb.collection("workflows");
let rows = [];
if (workflowId != "") {
  let lookup = workflows.find({workflowId: {$eq: workflowId}}, 1);
  rows = lookup.data ?? [];
}
if (leng(rows) == 0) {
  let fallback = workflows.find({}, 1);
  rows = fallback.data ?? [];
}
if (leng(rows) == 0) {
  return {ok: false, statusCode: 404, reason: "No workflow is available for transition"};
}

let workflow = rows[0];
workflowId = str(workflow.workflowId ?? workflowId).trim();
let previousState = str(workflow.state ?? "CREATED").upper();
let allowedStates = ["ACTIVE","CREATED","PENDING","PAUSED"];
let allowed = false;
for (state : allowedStates) {
  if (str(state ?? "").trim().upper() == previousState) {
    allowed = true;
  }
}
if (!allowed) {
  return {ok: false, statusCode: 409, reason: "Workflow is not in a startable state", workflowId: workflowId, state: previousState};
}

let context = type(workflow.context) == "object" ? workflow.context : {};
let retries = context.retries ?? 0;
if (retries == "") {
  retries = 0;
}
let steps = type(context.steps) == "object" ? context.steps : {};
let nowTs = datetime.now().isoformat();
let nextContext = {
  steps: steps,
  retries: retries,
  lastTransition: {
    action: "start",
    previousState: previousState,
    nextState: "RUNNING",
    actor: actor,
    at: nowTs
  }
};
let updatePayload = {
  state: "RUNNING",
  context: nextContext
};

if (dryRun) {
  return {ok: true, dryRun: true, workflowId: workflowId, previousState: previousState, nextState: "RUNNING", update: updatePayload};
}

let updateRes = workflows.update({workflowId: {$eq: workflowId}}, updatePayload);
if (updateRes.ok == false) {
  return {ok: false, statusCode: 500, reason: updateRes.error ?? "Failed to persist workflow transition", workflowId: workflowId, result: updateRes};
}

let events = vdb.collection("workflow_transition_events");
let eventId = crypto.uuid();
let eventRes = events.insert({
  eventId: eventId,
  workflowId: workflowId,
  action: "start",
  previousState: previousState,
  nextState: "RUNNING",
  actor: actor,
  createdAt: nowTs
});

return {ok: true, workflowId: workflowId, previousState: previousState, nextState: "RUNNING", eventId: eventId, eventRecorded: eventRes.ok ?? false, updated: true};

